package com.orderflow.notification.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notification_delivery",uniqueConstraints=@UniqueConstraint(name="uq_notification_channel",columnNames={"notification_id","channel"}))
public class NotificationDelivery{@Id private UUID id;@Column(name="notification_id",nullable=false)private UUID notificationId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private NotificationChannel channel;@Column(nullable=false,length=254)private String destination;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private NotificationDeliveryStatus status;@Column(name="attempt_count",nullable=false)private int attemptCount;@Column(name="last_failure_code",length=80)private String lastFailureCode;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Column(name="sent_at")private Instant sentAt;@Version private long version;protected NotificationDelivery(){}public NotificationDelivery(UUID notification,NotificationChannel channel,String destination,Instant now){id=UUID.randomUUID();notificationId=notification;this.channel=channel;this.destination=destination;status=NotificationDeliveryStatus.PENDING;createdAt=now;updatedAt=now;}public void processing(Instant at){if(status!=NotificationDeliveryStatus.PENDING)throw new IllegalStateException("Delivery is not pending");status=NotificationDeliveryStatus.PROCESSING;attemptCount++;updatedAt=at;}public void retry(Instant at,String code){status=NotificationDeliveryStatus.PENDING;lastFailureCode=code;updatedAt=at;}public void sent(Instant at){status=NotificationDeliveryStatus.SENT;sentAt=at;updatedAt=at;}public void failed(Instant at,String code){status=NotificationDeliveryStatus.FAILED;lastFailureCode=code;updatedAt=at;}public UUID getId(){return id;}public UUID getNotificationId(){return notificationId;}public NotificationChannel getChannel(){return channel;}public String getDestination(){return destination;}public NotificationDeliveryStatus getStatus(){return status;}public int getAttemptCount(){return attemptCount;}public String getLastFailureCode(){return lastFailureCode;}public Instant getSentAt(){return sentAt;}public Instant getUpdatedAt(){return updatedAt;}public long getVersion(){return version;}}
